import {
    eachDayOfInterval,
    endOfMonth,
    endOfWeek,
    format,
    isSameMonth,
    startOfMonth,
    startOfWeek,
} from 'date-fns';
import type { CalendarDay } from '../types/configs.types';
import { STATUS_BADGE } from '../data/configs.data';

type ApiDay = {
    status: string;
    check_in: string | null;
    check_out: string | null;
    notes: string | null;
};

function mapApiStatusToDay(api: ApiDay | undefined): Pick<CalendarDay, 'status' | 'line1' | 'line2' | 'badgeLabel'> {
    if (!api) {
        return {
            status: 'absence',
            line1: '',
            line2: '',
            badgeLabel: STATUS_BADGE.absence.label,
        };
    }
    const st = api.status;
    if (st === 'present') {
        return {
            status: 'attendance',
            line1: api.check_in ? `وقت الدخول: ${api.check_in}` : '',
            line2: api.check_out ? `وقت الخروج: ${api.check_out}` : '',
            badgeLabel: STATUS_BADGE.attendance.label,
        };
    }
    if (st === 'late') {
        return {
            status: 'late',
            line1: api.check_in ? `وقت الدخول: ${api.check_in}` : '',
            line2: api.check_out ? `وقت الخروج: ${api.check_out}` : '',
            badgeLabel: STATUS_BADGE.late.label,
        };
    }
    if (st === 'absent') {
        return {
            status: 'absence',
            line1: '',
            line2: '',
            badgeLabel: STATUS_BADGE.absence.label,
        };
    }
    if (st === 'vacation' || st === 'holiday' || st === 'leave') {
        return {
            status: 'vacation',
            line1: api.notes ? `ملاحظات: ${api.notes}` : '',
            line2: '',
            badgeLabel: STATUS_BADGE.vacation.label,
        };
    }
    return {
        status: 'inactive',
        line1: '',
        line2: '',
        badgeLabel: STATUS_BADGE.inactive.label,
    };
}

/** Saturday-first week to match WEEKDAYS_AR. */
export function buildMonthGridFromAttendance(
    year: number,
    month: number,
    attendanceByDate: Record<string, ApiDay>,
): CalendarDay[] {
    const monthAnchor = new Date(year, month - 1, 1);
    const mStart = startOfMonth(monthAnchor);
    const mEnd = endOfMonth(monthAnchor);
    const gridStart = startOfWeek(mStart, { weekStartsOn: 6 });
    const gridEnd = endOfWeek(mEnd, { weekStartsOn: 6 });
    const days = eachDayOfInterval({ start: gridStart, end: gridEnd });

    return days.map((d) => {
        const key = format(d, 'yyyy-MM-dd');
        const api = attendanceByDate[key];
        const inMonth = isSameMonth(d, mStart);
        const mapped = inMonth ? mapApiStatusToDay(api) : { status: 'inactive' as const, line1: '', line2: '', badgeLabel: STATUS_BADGE.inactive.label };
        return {
            day: Number(format(d, 'd')),
            isCurrentMonth: inMonth,
            ...mapped,
        };
    });
}
