import type { EmployeeAttendanceType } from '@/features/humanResources/types/employeeAttendance.types';

/** API may return a JSON array, a single employee object, or a keyed object. */
export function normalizeMonthlyAttendancePayload(payload: unknown): EmployeeAttendanceType | null {
    if (payload == null) return null;
    if (Array.isArray(payload)) {
        const first = payload[0];
        return first && typeof first === 'object' ? (first as EmployeeAttendanceType) : null;
    }
    if (typeof payload !== 'object') return null;
    const o = payload as Record<string, unknown>;
    if (o.attendance != null && typeof o.attendance === 'object') {
        return payload as EmployeeAttendanceType;
    }
    for (const v of Object.values(o)) {
        if (v && typeof v === 'object' && 'attendance' in (v as Record<string, unknown>)) {
            return v as EmployeeAttendanceType;
        }
    }
    return null;
}
