import { useCallback, useEffect, useMemo, useState } from 'react';
import { addMonths, format } from 'date-fns';
import { ar } from 'date-fns/locale';
import { toast } from 'sonner';
import DayCell from './DayCell';
import { WEEKDAYS_AR } from '../data/configs.data';
import { buildMonthGridFromAttendance } from '../utils/buildMonthGridFromAttendance';
import { normalizeMonthlyAttendancePayload } from '../utils/normalizeMonthlyAttendance';
import { endpoints } from '@/lib/axios/axios-global';
import { apiGet } from '@/lib/axios/axios-utils';
import { useResolvedEmployeeId } from '@/hooks/useResolvedEmployeeId';
import type { EmployeeAttendanceType } from '@/features/humanResources/types/employeeAttendance.types';
import { cn } from '@/lib/utils';

const AttendanceDeparture = () => {
    const employeeId = useResolvedEmployeeId();
    const [viewYear, setViewYear] = useState(() => new Date().getFullYear());
    const [viewMonth, setViewMonth] = useState(() => new Date().getMonth() + 1);
    const [loading, setLoading] = useState(false);
    const [monthBlock, setMonthBlock] = useState<EmployeeAttendanceType | null>(null);

    const monthLabel = useMemo(
        () => format(new Date(viewYear, viewMonth - 1, 1), 'MMMM yyyy', { locale: ar }),
        [viewYear, viewMonth],
    );

    const loadMonth = useCallback(async () => {
        if (employeeId == null) {
            setMonthBlock(null);
            return;
        }
        setLoading(true);
        try {
            const res = await apiGet({
                endpoint: endpoints.employeeAttendance.attendance,
                queryParams: {
                    employee_id: String(employeeId),
                    month: viewMonth,
                    year: viewYear,
                },
            });
            const block = normalizeMonthlyAttendancePayload(res.data?.data);
            setMonthBlock(block);
        } catch {
            setMonthBlock(null);
            toast.error('تعذر تحميل حضور الشهر');
        } finally {
            setLoading(false);
        }
    }, [employeeId, viewMonth, viewYear]);

    useEffect(() => {
        void loadMonth();
    }, [loadMonth]);

    const cells = useMemo(() => {
        const byDate = (monthBlock?.attendance ?? {}) as Record<
            string,
            { status: string; check_in: string | null; check_out: string | null; notes: string | null }
        >;
        return buildMonthGridFromAttendance(viewYear, viewMonth, byDate);
    }, [monthBlock, viewYear, viewMonth]);

    const summary = monthBlock?.summary;
    const progressPct = useMemo(() => {
        if (!summary || summary.total_days <= 0) return 0;
        const done = summary.present + summary.late;
        return Math.min(100, Math.round((done / summary.total_days) * 100));
    }, [summary]);

    const shiftMonth = (delta: number) => {
        const base = new Date(viewYear, viewMonth - 1, 1);
        const next = addMonths(base, delta);
        setViewYear(next.getFullYear());
        setViewMonth(next.getMonth() + 1);
    };

    if (employeeId == null) {
        return (
            <section className="mt-10 font-cairo text-center text-sm text-neutral-600" dir="rtl">
                تعذر عرض تقويم الحضور بدون ربط حسابك بسجل موظف.
            </section>
        );
    }

    return (
        <section className="mt-10 font-cairo" dir="rtl">
            <div className="mb-4 flex flex-wrap items-center justify-between gap-3 rounded-md border border-[#e0e0e0] bg-white px-3 py-2">
                <button
                    type="button"
                    className="rounded border border-neutral-300 bg-neutral-50 px-3 py-1.5 text-sm hover:bg-neutral-100"
                    onClick={() => shiftMonth(-1)}
                    aria-label="الشهر السابق"
                >
                    ‹ الشهر السابق
                </button>
                <p className="text-base font-semibold text-neutral-800">{monthLabel}</p>
                <button
                    type="button"
                    className="rounded border border-neutral-300 bg-neutral-50 px-3 py-1.5 text-sm hover:bg-neutral-100"
                    onClick={() => shiftMonth(1)}
                    aria-label="الشهر التالي"
                >
                    الشهر التالي ›
                </button>
            </div>

            {summary ? (
                <div className="mb-4 rounded-md border border-primery-blue-200 bg-primery-blue-50 px-3 py-3 text-primery-blue-900">
                    <div className="mb-2 flex flex-wrap justify-between gap-2 text-sm">
                        <span>تقدم الحضور هذا الشهر</span>
                        <span className="font-semibold tabular-nums">{progressPct}%</span>
                    </div>
                    <div className="h-2 overflow-hidden rounded-full bg-primery-blue-100">
                        <div
                            className={cn('h-2 rounded-full bg-primery-blue-500 transition-all')}
                            style={{ width: `${progressPct}%` }}
                        />
                    </div>
                    <p className="mt-2 text-xs text-primery-blue-800">
                        حضور {summary.present + summary.late} من {summary.total_days} يوماً في التقويم — غياب {summary.absent} —
                        تأخير {summary.late} — إجازة {summary.leave}
                    </p>
                </div>
            ) : null}

            <div className="mb-4 rounded-t-md bg-slate-100/90 px-2 py-3">
                <div className="grid grid-cols-7 gap-2 text-center text-sm font-medium text-neutral-700">
                    {WEEKDAYS_AR.map((name) => (
                        <div key={name} className="px-1">
                            {name}
                        </div>
                    ))}
                </div>
            </div>

            <div className="relative grid grid-cols-7 gap-2 border border-[#e0e0e0] border-t-0 bg-neutral-50/30 p-2">
                {loading ? (
                    <div className="col-span-7 py-16 text-center text-sm text-neutral-500">جاري التحميل…</div>
                ) : (
                    cells.map((cell, idx) => <DayCell key={`${cell.day}-${cell.isCurrentMonth}-${idx}`} cell={cell} />)
                )}
            </div>
        </section>
    );
};

export default AttendanceDeparture;
