import { CalendarDay } from '../types/configs.types';
import { STATUS_BADGE } from '../data/configs.data';
import { cn } from '@/lib/utils';

export default function DayCell({ cell }: { cell: CalendarDay }) {
    const badge = STATUS_BADGE[cell.status];
    const inactiveCell = cell.status === 'inactive' && cell.isCurrentMonth;

    return (
        <div
            className={cn(
                'flex min-h-[140px] flex-col rounded border border-[#e0e0e0] bg-white p-3 text-sm',
                !cell.isCurrentMonth && 'bg-[#f8f9fa] opacity-80',
                inactiveCell && 'bg-[#f8f9fa]',
            )}
        >
            <div className="mb-2 flex items-start justify-between gap-2">
                <span className="text-base font-medium text-neutral-800">{cell.day}</span>
            </div>
            <div className="min-h-[36px] flex-1 space-y-1 text-xs text-neutral-600">
                {cell.line1 ? <p className="leading-snug">{cell.line1}</p> : null}
                {cell.line2 ? <p className="leading-snug">{cell.line2}</p> : null}
            </div>
            <div
                className={cn(
                    'mt-2 w-full rounded px-2 py-1.5 text-center text-xs font-medium',
                    badge.className,
                )}
            >
                {cell.badgeLabel}
            </div>
        </div>
    );
}